using System.Net.Http; using System.Net.Http.Json; using System.Windows; using Microsoft.Win32; namespace CloudClient; public partial class MainWindow:Window { readonly HttpClient http=new(); readonly string server; List<Storage> stores=new(); Storage? current; string path=""; public MainWindow(string url){InitializeComponent();server=url;Loaded+=async(_,__)=>await Load();CloudGrid.MouseDoubleClick+=async(_,__)=>await OpenSelected();NewFolderButton.Click+=async(_,__)=>await NewFolder();UploadButton.Click+=async(_,__)=>await Upload();} async Task Load(){try{stores=await http.GetFromJsonAsync<List<Storage>>(server+"/api/storage")??new();current=stores.FirstOrDefault();if(current!=null)await LoadFiles();}catch(Exception e){MessageBox.Show(e.Message,"Verbindungsfehler");}} async Task LoadFiles(){if(current==null)return;var u=$"{server}/api/files?storageId={Uri.EscapeDataString(current.Id)}&path={Uri.EscapeDataString(path)}";var d=await http.GetFromJsonAsync<List<FileItem>>(u)??new();CloudGrid.ItemsSource=d.Select(x=>new Row(x.Name,x.IsDirectory?"Ordner":current.Role,x.IsDirectory?"—":Format(x.Size),x.IsDirectory?"Ordner":"Bereit",x.IsDirectory)).ToList();} async Task OpenSelected(){if(CloudGrid.SelectedItem is not Row r||!r.IsDirectory)return;path=string.IsNullOrEmpty(path)?r.Name:System.IO.Path.Combine(path,r.Name);await LoadFiles();} async Task NewFolder(){if(current==null)return;var name=Microsoft.VisualBasic.Interaction.InputBox("Name des neuen Ordners:","Neuer Ordner");if(string.IsNullOrWhiteSpace(name))return;var res=await http.PostAsJsonAsync(server+"/api/folders",new{StorageId=current.Id,Path=path,Name=name});if(!res.IsSuccessStatusCode){MessageBox.Show("Ordner konnte nicht angelegt werden.");return;}await LoadFiles();} async Task Upload(){if(current==null)return;var d=new OpenFileDialog();if(d.ShowDialog()!=true)return;await using var fs=System.IO.File.OpenRead(d.FileName);using var content=new StreamContent(fs);var url=$"{server}/api/upload?storageId={Uri.EscapeDataString(current.Id)}&path={Uri.EscapeDataString(path)}&name={Uri.EscapeDataString(System.IO.Path.GetFileName(d.FileName))}";var r=await http.PostAsync(url,content);if(!r.IsSuccessStatusCode){MessageBox.Show("Upload fehlgeschlagen.");return;}await LoadFiles();} static string Format(long b)=>b>=1073741824?$"{b/1073741824d:N2} GB":b>=1048576?$"{b/1048576d:N1} MB":$"{b/1024d:N0} KB"; sealed class Storage{public string Id{get;set;}="";public string Name{get;set;}="";public string Role{get;set;}="";public long QuotaBytes{get;set;}} sealed class FileItem{public string Name{get;set;}="";public bool IsDirectory{get;set;}public long Size{get;set;}} sealed record Row(string Name,string Role,string Quota,string Status,bool IsDirectory); }